function fewestRepaints(blocks: string, k: number): number {
  let best = Infinity;
  for (let i = 0; i + k <= blocks.length; i++) {
    let whites = 0;
    for (let j = i; j < i + k; j++) if (blocks[j] === "W") whites++;
    best = Math.min(best, whites);
  }
  return best;
}

