function fewestRepaints(blocks: string, k: number): number {
  let whites = 0;
  for (let i = 0; i < k; i++) if (blocks[i] === "W") whites++;
  let best = whites;
  for (let i = k; i < blocks.length; i++) {
    if (blocks[i] === "W") whites++;
    if (blocks[i - k] === "W") whites--;
    best = Math.min(best, whites);
  }
  return best;
}

